insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','{"title":"A brighter walk home starts here","summary":"Light the public path from the Eastbridge campus gate to the bus stop before winter evening classes.","problem":"Evening classes finish after sunset, but the public path from the Eastbridge campus gate to the bus shelter has gaps between lights. Students want to see the route clearly and wait for the bus without standing in the dark. The student path audit illustrates the concern; it is sample evidence, not a measured safety study.","action":"Assess the public path from the Eastbridge campus gate to the bus shelter and publish a pedestrian-lighting plan before winter evening classes.","recipient":"Riverton Public Works (fictional)","topic":"Safer streets","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000001","goal":1000,"deadline":"2027-01-05","evidence":[{"label":"Sample student path audit — illustrative evidence","url":"https://example.org/student-path-audit"}],"verification":"email","identities":["full_name","first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',684,28,42,'2026-10-18T16:22:37.978Z') on conflict(id) do nothing;
insert into public.petition_sources(petition_id,label,url) select '20000000-0000-4000-8000-000000000001','Sample student path audit — illustrative evidence','https://example.org/student-path-audit' where not exists(select 1 from public.petition_sources where petition_id='20000000-0000-4000-8000-000000000001' and url='https://example.org/student-path-audit');
insert into public.petition_updates(petition_id,author_id,body) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','We shared the student path audit and 500 sample signatures at the listening session. Next milestone: 750 voices. We are asking for a published lighting plan before winter evening classes.' where not exists(select 1 from public.petition_updates where petition_id='20000000-0000-4000-8000-000000000001');
insert into public.petition_edits(petition_id,author_id,body,previous_content) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','Clarified the requested action: lighting assessment and a public implementation plan. No eligibility rules changed.','{"title":"A brighter walk home starts here","summary":"Light the public path from the Eastbridge campus gate to the bus stop before winter evening classes.","problem":"Evening classes finish after sunset, but the public path from the Eastbridge campus gate to the bus shelter has gaps between lights. Students want to see the route clearly and wait for the bus without standing in the dark. The student path audit illustrates the concern; it is sample evidence, not a measured safety study.","action":"Assess the public path from the Eastbridge campus gate to the bus shelter and publish a pedestrian-lighting plan before winter evening classes.","recipient":"Riverton Public Works (fictional)","topic":"Safer streets","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000001","goal":1000,"deadline":"2027-01-05","evidence":[{"label":"Sample student path audit — illustrative evidence","url":"https://example.org/student-path-audit"}],"verification":"email","identities":["full_name","first_name_last_initial","anonymous"],"customRule":""}'::jsonb where not exists(select 1 from public.petition_edits where petition_id='20000000-0000-4000-8000-000000000001');
