insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','{"title":"More shade. Cooler school days.","summary":"Plant shade trees around the Riverton school courtyard and publish a maintenance plan.","problem":"Students use the school courtyard for breaks and outdoor activities, but the seating area has little shade. The request asks the district to assess suitable planting sites and explain how new trees would be cared for.","action":"Plant shade trees around the Riverton school courtyard","recipient":"Riverton Unified School Board (fictional)","topic":"Environment","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000002","goal":500,"deadline":"2027-02-21","evidence":[],"verification":"account","identities":["first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',328,31,39,'2026-10-17T16:22:37.979Z') on conflict(id) do nothing;
